{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table prd_db.beardo.beardo_inventory_fact_items as WITH sku_mapping as ( select distinct parent_sku, child_sku,child_quantity from ( (select trim(upper(\"Product Code\")) as parent_sku, trim(upper(\"Component Product Code\")) as child_sku, try_cast(trim(upper(\"Component Quantity\")) as int) as child_quantity from datalake_db.beardo.beardo_product_item_master order by 2 desc) union all (select trim(upper(\"Product Code\")) as parent_sku, trim(upper(\"Component Product Code\")) as child_sku, try_cast(trim(upper(\"Component Quantity\")) as int) as child_quantity from datalake_db.beardo.unicommerce_beardo_get_item_master order by 2 desc) ) ), daily_sku_sales AS ( SELECT CAST(order_date AS DATE) AS date_day, upper(Warehouse_Name) as Warehouse, COALESCE(sm.child_sku, s.sku) sku, SUM(s.quantity * COALESCE(cast(sm.child_quantity as int), 1)) AS daily_quantity FROM prd_db.beardo.DWH_SALES_CONSOLIDATED s LEFT JOIN sku_mapping sm ON lower(s.sku) = lower(sm.parent_sku) WHERE replace(replace(sku,\'-\',\'_\'),\'_\',\'\') is not null and not(order_status = \'CANCELLED\' or shippingpackagestatus = \'CANCELLED\' or shipping_status = \'CANCELLED\') GROUP BY 1,2,3 ), daily_inventory_snapshot AS ( SELECT DATE(timestamp) date_day, replace(i.skucode,\'`\',\'\') sku, upper(facility) as Warehouse, sum(cast(inventory as INT)) as inventory_that_day, CASE WHEN ifnull(sum(cast(inventory as INT)),0) > 0 THEN 1 ELSE 0 END AS has_inventory, CASE WHEN ifnull(sum(cast(inventory as INT)),0) < 4 THEN 1 ELSE 0 END AS is_oos FROM datalake_db.beardo.unicommerce_beardo_get_inventory_snapshot i GROUP BY 1,2,3 ORDER BY 1 DESC ), all_sku_dates AS ( SELECT DISTINCT c.date_day, d.sku, d.warehouse FROM daily_inventory_snapshot AS d CROSS JOIN ( SELECT DATEADD(day, SEQ4(), \'2026-07-01\'::DATE) AS date_day FROM TABLE(GENERATOR(ROWCOUNT => 10000)) WHERE DATEADD(day, SEQ4(), \'2026-07-01\'::DATE) <= CURRENT_DATE() ) AS c ), sales_metrics AS ( SELECT a.date_day, a.sku, a.warehouse, COALESCE(s.daily_quantity, 0) AS daily_quantity, COALESCE(i.has_inventory, 0) AS has_inventory_today, inventory_that_day, ifnull(i.is_oos, 1) AS is_oos_today, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS L7_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS L14_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS L30_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS L45_day_sales, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS inventory_days_7, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS inventory_days_14, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS inventory_days_30, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS inventory_days_45, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS oos_days_7, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS oos_days_14, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS oos_days_30, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.warehouse ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS oos_days_45 FROM all_sku_dates AS a LEFT JOIN daily_sku_sales AS s ON a.date_day = s.date_day AND a.sku = s.sku and lower(a.warehouse) = lower(s.warehouse) LEFT JOIN daily_inventory_snapshot AS i ON a.date_day = i.date_day AND a.sku = i.sku and lower(a.warehouse) = lower(i.warehouse) order by 1 desc ) SELECT date_day as data_fetch_date, s.sku, warehouse, p.product_name, p.category as product_category, p.image_url, s.daily_quantity, s.has_inventory_today, s.inventory_that_day as available_inventory, L7_day_sales sold_quantity_7_days, L14_day_sales sold_quantity_14_days, L30_day_sales sold_quantity_30_days, L45_day_sales sold_quantity_45_days, inventory_days_7, inventory_days_14, inventory_days_30, inventory_days_45, oos_days_7, oos_days_14, oos_days_30, oos_days_45 FROM sales_metrics s LEFT JOIN (select upper(trim(\"Product Code\")) as sku, upper(name) as product_name, \"Image Url\" as image_url, \"Category Name\" as category from datalake_db.beardo.unicommerce_beardo_get_product_master qualify row_number() over (partition by upper(trim(\"Product Code\")) order by 1) = 1 ) p on upper(p.sku) = upper(s.sku) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from PRD_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            